        // No-op: Spendable vault doesn't use yield protocols
    }

    /**
     * @notice No protocol withdrawal (Spendable doesn't earn yield)
     */
    function _withdrawFromProtocol(uint256 amount) internal pure override returns (uint256) {
        // No-op: Spendable vault doesn't use yield protocols
